"""Generate CAD-derived technical SVG views and a simulated motion demonstrator from central parameters."""
import json
from pathlib import Path

ROOT=Path(__file__).parents[1]; P=json.loads((ROOT/'hardware/mechanical/source/parameters.json').read_text())
OUT=ROOT/'hardware/mechanical/renders'; OUT.mkdir(parents=True,exist_ok=True)
W,D,H=P['overall']['width'],P['overall']['depth'],P['overall']['height']
def svg(title, body, note):
 return f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="760" viewBox="0 0 1200 760"><rect width="1200" height="760" fill="#f3f4f1"/><text x="55" y="60" font-family="Arial" font-size="32" font-weight="700" fill="#152126">LOOMFORGE / {title}</text><text x="55" y="94" font-family="Arial" font-size="16" fill="#507077">LF-P1-R02 - CAD-derived technical illustration - not physical validation</text>{body}<text x="55" y="720" font-family="Arial" font-size="15" fill="#526166">{note}</text></svg>'''
def rect(x,y,w,h,fill,stroke='#152126',r=4): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>'
def line(x1,y1,x2,y2,c='#152126',w=3): return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{c}" stroke-width="{w}"/>'
base=rect(170,530,760,110,'#20282c',r=16)+rect(215,495,670,36,'#d6d7d2')
sides=rect(190,220,72,310,'#e2e3de')+rect(838,220,72,310,'#e2e3de')
spine=rect(795,180,76,320,'#20282c'); rails=line(350,235,770,235,'#6e7b80',10)+line(350,270,770,270,'#6e7b80',10)
head=rect(535,250,75,125,'#344248')+rect(547,370,50,55,'#b8b8b2')+rect(550,425,44,44,'#809395')
deck=rect(370,460,125,48,'#257889')+rect(260,475,360,48,'#344248')
tray=''.join(rect(275+i*26,485,16,22,'#526267') for i in range(12))
guard='<rect x="295" y="180" width="485" height="315" fill="#6bc4cc" fill-opacity=".20" stroke="#3c8f97" stroke-width="4"/>'
lights=rect(355,160,145,12,'#fff9d4')+rect(585,160,145,12,'#fff9d4')+rect(460,130,160,12,'#0ca2a1')
common=base+sides+spine+rails+head+deck+tray+guard+lights
(OUT/'front-elevation.svg').write_text(svg('FRONT ELEVATION',common,'Overall envelope: 560 W x 430 D x 520 H mm. Clear guard and moving head are conceptual CAD geometry.'),encoding='utf-8')
(OUT/'front-hero.svg').write_text(svg('FRONT THREE-QUARTER',common+'<path d="M910 530 L1005 485 L1005 375 L910 420Z" fill="#1a2226" stroke="#152126" stroke-width="2"/>','Warm folded panels, graphite structure, cyan fixture/status accents. Render substitute pending CAD renderer.'),encoding='utf-8')
(OUT/'open-loading.svg').write_text(svg('OPEN LOADING DOOR',common+'<path d="M295 180 L295 495 L120 410 L120 100Z" fill="#6bc4cc" fill-opacity=".20" stroke="#3c8f97" stroke-width="4"/><text x="110" y="125" font-family="Arial" font-size="18">105 degree upward hinge sweep</text>','Upward-opening guard selected: preserves bench-front clearance and keeps loading deck accessible; pinch/strut force require validation.'),encoding='utf-8')
(OUT/'insertion-closeup.svg').write_text(svg('INSERTION HEAD',rect(360,140,360,440,'#20282c')+line(430,235,650,235,'#6e7b80',12)+rect(510,255,70,135,'#344248')+rect(522,390,46,20,'#b8b8b2')+rect(526,410,38,70,'#809395')+rect(488,490,114,36,'#257889')+rect(422,535,245,42,'#344248')+'<path d="M545 480 C545 505 520 510 505 525" fill="none" stroke="#d55542" stroke-width="6"/>','Split guide jaws open after gripper release; wire comb supports slack. Geometry is experimental and needs insertion trials.'),encoding='utf-8')
(OUT/'rear-service.svg').write_text(svg('REAR THREE-QUARTER SERVICE',base+sides+rect(330,200,360,300,'#20282c')+''.join(rect(375+i*30,240,12,115,'#0c1012') for i in range(10)),'Rear spine conceals cable chain/electronics routing; service panel requires power isolation.'),encoding='utf-8')
(OUT/'side-elevation.svg').write_text(svg('SIDE ELEVATION',rect(260,530,500,110,'#20282c',r=16)+rect(360,210,85,320,'#e2e3de')+rect(445,170,140,315,'#6bc4cc','#3c8f97')+rect(560,250,75,235,'#20282c')+rect(280,430,220,45,'#344248'),'Side support/spine and transparent guard envelope shown. Door sweep requires physical review.'),encoding='utf-8')
(OUT/'top-view.svg').write_text(svg('TOP VIEW',rect(180,190,760,390,'#20282c',r=16)+rect(240,240,600,75,'#e2e3de')+rect(420,350,120,90,'#257889')+rect(240,470,420,70,'#344248')+''.join(rect(255+i*30,485,18,30,'#526267') for i in range(12)),'Plan view identifies front deck, 12-slot tray, fixture and rear structural/service spine.'),encoding='utf-8')
(OUT/'internal-cutaway.svg').write_text(svg('INTERNAL CUTAWAY',base+spine+rails+head+deck+tray+lights+'<path d="M295 180 L780 180 L780 495 L650 495 Z" fill="#ffffff" fill-opacity=".55"/>','Cutaway removes right guard/support to expose rails, head, lighting, fixture and tray.'),encoding='utf-8')
(OUT/'exploded-assembly.svg').write_text(svg('EXPLODED ASSEMBLY',rect(175,550,760,75,'#20282c')+rect(250,440,650,38,'#e2e3de')+rect(610,320,120,52,'#20282c')+rect(450,240,120,55,'#344248')+rect(350,160,280,30,'#6bc4cc')+'<text x="190" y="650" font-family="Arial" font-size="18">LF-100 plinth</text><text x="270" y="430" font-family="Arial" font-size="18">LF-120 supports / LF-110 spine</text><text x="620" y="310" font-family="Arial" font-size="18">LF-310 fixture</text><text x="450" y="230" font-family="Arial" font-size="18">LF-200 head</text>','Callouts map to hardware/mechanical/parts.csv. Fasteners/purchased components require release-level CAD.'),encoding='utf-8')
(OUT/'fixture-closeup.svg').write_text(svg('CONNECTOR FIXTURE',rect(390,330,420,100,'#257889')+rect(520,270,150,65,'#d5c44a')+line(530,290,530,315,'#152126',5)+line(560,290,560,315,'#152126',5)+line(590,290,590,315,'#152126',5)+line(620,290,620,315,'#152126',5)+'<text x="400" y="470" font-family="Arial" font-size="18">Dowel-located cartridge, mating test plug and front extraction clearance</text>','Controlled connector drawing remains required before defining nest and cavity coordinates.'),encoding='utf-8')
(OUT/'lighting-camera.svg').write_text(svg('LIGHTING AND CAMERA',base+spine+deck+tray+rect(420,118,190,26,'#20282c')+rect(335,155,135,15,'#fff9d4')+rect(610,155,135,15,'#fff9d4')+rect(475,145,120,15,'#80e4df')+'<text x="330" y="200" font-family="Arial" font-size="18">work lights / vision light / camera / baffle zones</text>','Status guide is intentionally excluded from camera exposure zone.'),encoding='utf-8')
(OUT/'operator-loading-sequence.svg').write_text(svg('OPERATOR LOADING SEQUENCE',rect(130,250,190,220,'#e2e3de')+rect(360,250,190,220,'#e2e3de')+rect(590,250,190,220,'#e2e3de')+rect(820,250,190,220,'#e2e3de')+'<text x="150" y="300" font-family="Arial" font-size="18">1 OPEN GUARD</text><text x="150" y="340" font-family="Arial" font-size="18">2 LOAD SLOT</text><text x="380" y="300" font-family="Arial" font-size="18">3 ROUTE COMB</text><text x="610" y="300" font-family="Arial" font-size="18">4 CLOSE/VALIDATE</text><text x="840" y="300" font-family="Arial" font-size="18">5 REMOVE AFTER TEST</text>','Operator performs presentation and final removal. This is supervised equipment, not unattended assembly.'),encoding='utf-8')
motion=(ROOT/'reports'/'motion-demonstration.html'); motion.write_text(f'''<!doctype html><title>LoomForge simulated motion</title><style>body{{font-family:Arial;background:#152126;color:#eef3f1}}svg{{max-width:100%;background:#f3f4f1}}#tag{{color:#64d2ce}}</style><h1>LoomForge <span id="tag">SIMULATED MOTION</span></h1><p id="s"></p><svg viewBox="0 0 900 520"><rect x="80" y="400" width="700" height="80" rx="12" fill="#20282c"/><rect x="150" y="120" width="55" height="280" fill="#e2e3de"/><rect x="695" y="100" width="60" height="300" fill="#20282c"/><rect x="300" y="355" width="90" height="35" fill="#257889"/><rect x="190" y="370" width="320" height="30" fill="#344248" id="tray"/><rect x="450" y="160" width="68" height="120" fill="#344248" id="head"/><rect x="462" y="280" width="44" height="55" fill="#809395" id="guide"/><path d="M300 370 C330 340 370 340 410 355" fill="none" stroke="#d55542" stroke-width="5" id="wire"/></svg><script>let a=[['Operator loads indexed wire into tray',450,160],['Guard closes; controller ready',450,160],['Head picks terminal at tray slot',250,280],['Head transfers to fixture',405,220],['Guided simulated insertion',405,310],['Guide opens; gripper releases',405,250],['Electrical mapping verification',405,220],['Completed assembly removed by operator',450,160],['Fault example: force limit -> recovery required',405,270]];let i=0;setInterval(()=>{{let x=a[i];s.textContent=x[0];head.setAttribute('x',x[1]);guide.setAttribute('x',x[1]+12);guide.setAttribute('y',x[2]+120);i=(i+1)%a.length}},1600)</script><p>Uses the same LF-P1-R02 layout parameters as the conceptual CAD. Simulated only; no cycle-time or insertion-performance claim.</p>''',encoding='utf-8')
print('Generated',len(list(OUT.glob('*.svg'))),'technical SVG views and',motion)
if __name__=='__main__': pass
